INSERT INTO `consent_versions` (`version`, `text`, `published_at`) VALUES ('2', 'Overture fills in each application for me from the resume and facts I saved. It sends an application only after I approve it, and the answers, resume and cover letter it sends are the ones I approved. Applications come from my trial or plan, a failed application is never charged, and my plan renews until I cancel it.', 1795305600);
